"""Tests for the GitHub Release notes extractor, tools/release_notes.py (#498)."""

from __future__ import annotations

import re
from pathlib import Path

import pytest
from tools.release_notes import CHANGELOG, main, release_notes

SAMPLE = """\
# Changelog

## [Unreleased]

## [2.0.0] - 2027-01-02

### Breaking Changes

- Something big.

## [1.0.0] - 2026-01-01

- First release.

<!-- generated by git-cliff -->

[1.0.0]: https://example.com/compare/v0.9.0...v1.0.0
[2.0.0]: https://example.com/compare/v1.0.0...v2.0.0
"""


def test_extracts_one_section_without_its_heading() -> None:
    """The section body runs up to the next ``## `` heading."""
    assert release_notes(SAMPLE, "v2.0.0") == "### Breaking Changes\n\n- Something big.\n"


def test_last_section_drops_trailing_comments_and_link_definitions() -> None:
    """Link reference definitions and comments at the end of the file are not release notes."""
    assert release_notes(SAMPLE, "v1.0.0") == "- First release.\n"


@pytest.mark.parametrize(
    ("changelog", "tag", "message"),
    [
        (SAMPLE, "1.0.0", "not a vMAJOR.MINOR.PATCH tag"),
        (SAMPLE, "v1.0.0rc1", "not a vMAJOR.MINOR.PATCH tag"),
        (SAMPLE, "v3.0.0", r"no '## \[3.0.0\] - YYYY-MM-DD' section"),
        (
            "## [Unreleased]\n\n## [3.0.0] - 2027-03-03\n\n## [2.0.0] - 2027-01-02\n",
            "v3.0.0",
            "empty",
        ),
    ],
)
def test_unprepared_changelogs_are_rejected(changelog: str, tag: str, message: str) -> None:
    """A bad tag, or a missing or empty section, fails before anything is published."""
    with pytest.raises(ValueError, match=message):
        release_notes(changelog, tag)


def test_every_released_version_has_notes() -> None:
    """Every dated section of the real CHANGELOG.md yields notes with no stray headings."""
    text = CHANGELOG.read_text(encoding="utf-8")
    versions = re.findall(r"^## \[(\d+\.\d+\.\d+)\] - \d{4}-\d{2}-\d{2}$", text, re.MULTILINE)
    assert "1.1.0" in versions
    for version in versions:
        notes = release_notes(text, f"v{version}")
        assert not re.search(r"^## |^\[[^\]]+\]: |<!--", notes, re.MULTILINE), version


def test_1_1_0_notes_announce_the_python_3_10_drop() -> None:
    """The 1.1.0 notes lead with the new minimum Python and link the upgrade guide."""
    notes = release_notes(CHANGELOG.read_text(encoding="utf-8"), "v1.1.0")
    first = notes.split("\n\n", 1)[0]
    assert "requires Python 3.11 or newer" in first
    assert "findfmt<1.1" in first
    assert "Upgrading to 1.1" in notes
    assert "### Breaking Changes" in notes


def test_main_prints_notes_or_fails(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    """The CLI prints the notes on success and exits 1 with an error otherwise."""
    changelog = tmp_path / "CHANGELOG.md"
    changelog.write_text(SAMPLE, encoding="utf-8")
    assert main(["--tag", "v2.0.0", "--changelog", str(changelog)]) == 0
    assert capsys.readouterr().out == "### Breaking Changes\n\n- Something big.\n"
    assert main(["--tag", "v9.9.9", "--changelog", str(changelog)]) == 1
    assert "error: CHANGELOG.md has no" in capsys.readouterr().err
